from datetime import date, timedelta
hol = {date(2021,9,13), date(2021,9,14), date(2021,10,1)}
def workday(start, n, hol):
    d = start
    count = 0
    while count < n:
        d += timedelta(days=1)
        if d.weekday() < 5 and d not in hol:
            count += 1
    return d
start = date(2021,9,1)
